  // Check if the download is an extension and not approved
  if (download.IsExtension() && !download.IsApproved()) {
    // If off-store extension installations are enabled, consider it dangerous
    if (IsOffStoreExtensionsEnabled()) {
      return true;
    }
  }

  // Evaluate danger based on file extension
  if (IsDangerousExtension(suggested_path)) {
    // If the user has not interacted with the referrer page before, it's more dangerous
    if (!visited_referrer_before) {
      return true;
    }
  }

  // If no danger criteria are met, return false
  return false;
}

