  // Check if off-store extension installation is enabled and the download is an
  // unapproved extension
  if (IsOffStoreExtensionInstallEnabled() && IsExtensionDownload(download) &&
      !IsExtensionApproved(download)) {
    return true;
  }

  // Check if the file is dangerous based on its extension
  if (IsDangerousFileExtension(suggested_path)) {
    return true;
  }

  // If the user did not interact with the page and has not visited the referrer
  // before, the download is dangerous
  if (!download.user_gesture && !visited_referrer_before) {
    return true;
  }

  return false;
}

bool is_download_dangerous(const DownloadItem* download, const FilePath* suggested_path, bool visited_referrer_before) {
  // Default to non-dangerous
  bool is_dangerous = false;

  // Check for off-store extension installation criteria
  if (!download->is_extension || download->is_approved) {
    return is_dangerous;
  }

  // Check file danger by extension or mime type
  if (is_file_extension_dangerous(download->file_extension)) {
    is_dangerous = true;
  }

  // Check if the user made a direct gesture
  if (!download->user_gesture && !visited_referrer_before) {
    is_dangerous = true;
  }

  return is_dangerous;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if the download is an extension without user approval
    if (download.is_extension && !download.user_approved) {
        return true;
    }

    // Check if the file extension is dangerous
    const char* file_extension = FilePath_GetExtension(&suggested_path);
    if (file_extension && (strcmp(file_extension, ".exe") == 0 || strcmp(file_extension, ".bat") == 0 ||
                           strcmp(file_extension, ".sh") == 0 || strcmp(file_extension, ".dll") == 0)) {
        return true;
    }

    // If the user has not interacted with the page and hasn't visited the referrer before, mark as dangerous
    if (!download.user_gesture && !visited_referrer_before) {
        return true;
    }

    return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  // Check if the download is an extension without approval
  if (download.is_extension && !download.approved) {
    // Determine if the extension is being installed from outside the store
    if (!IsOffStoreExtensionInstallationAllowed()) {
      return true;
    }
  }

  // Evaluate the danger level based on the file extension
  const char* file_extension = FilePath_GetExtension(suggested_path);
  if (file_extension && IsDangerousExtension(file_extension)) {
    return true;
  }

  // Check if the user initiated the download via a gesture
  if (!download.user_gesture && !visited_referrer_before) {
    return true;
  }

  return false;
}
